declare(strict_types=1);

namespace LongitudeOne\SpatialDecoder\Tests\Functional\Postgis;

use LongitudeOne\Core\Enum\CoordinateDimensionEnum;
use LongitudeOne\SpatialDecoder\Exception\InvalidArgumentException;
use LongitudeOne\SpatialDecoder\Strategy\WkbDecoderStrategy;
use LongitudeOne\SpatialTypes\Builder\SpatialBuilder;
use LongitudeOne\SpatialTypes\Interfaces\SpatialInterface;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Offline interoperability checks against the supplied PostGIS export.
 *
 * Original corpus query supplied with the reference WKB values:
 *
 * WITH exemples (type_geometrique, simple_xy, complexe_xy) AS (
 *     VALUES
 *         ('Point', '(2 48)', '(-3.125 44.0625)'),
 *         ('LineString', '(2 48,3 49)', '(-3.5 44,0 46.25,2 45,4.5 48)'),
 *         ('Polygon', '((0 0,4 0,0 4,0 0))', '((0 0,8 0,8 8,0 8,0 0),(2 2,2 4,4 4,4 2,2 2))'),
 *         ('MultiPoint', '((2 48))', '((-3.125 44),(0 46.25),(2 48))'),
 *         ('MultiLineString', '((0 0,2 2))', '((0 0,2 2,4 0),(5 1,7 3,8 2))'),
 *         ('MultiPolygon', '(((0 0,4 0,0 4,0 0)))', '(((0 0,8 0,8 8,0 8,0 0),(2 2,2 4,4 4,4 2,2 2)),((10 0,13 0,10 3,10 0)))'),
 *         ('GeometryCollection', '(POINT(2 48))', '(POINT EMPTY,LINESTRING(0 0,2 2),GEOMETRYCOLLECTION(POINT(3 4),POLYGON((5 5,7 5,5 7,5 5))))'),
 *         ('CircularString', '(0 0,1 1,2 0)', '(0 0,1 1,2 0,3 -1,4 0)'),
 *         ('CompoundCurve', '((0 0,2 0),CIRCULARSTRING(2 0,3 1,4 0))', '(CIRCULARSTRING(0 0,1 1,2 0),(2 0,3 -1,4 -1),CIRCULARSTRING(4 -1,5 0,6 -1))'),
 *         ('CurvePolygon', '(CIRCULARSTRING(0 0,2 2,4 0,2 -2,0 0))', '(COMPOUNDCURVE((0 0,8 0),CIRCULARSTRING(8 0,10 4,8 8),(8 8,0 8,0 0)),(2 2,2 4,4 4,4 2,2 2))'),
 *         ('MultiCurve', '((0 0,2 2))', '((0 0,2 2),CIRCULARSTRING(3 0,4 1,5 0),COMPOUNDCURVE((6 0,7 0),CIRCULARSTRING(7 0,8 1,9 0)))'),
 *         ('MultiSurface', '(((0 0,4 0,0 4,0 0)))', '(((0 0,4 0,0 4,0 0)),CURVEPOLYGON(CIRCULARSTRING(6 0,8 2,10 0,8 -2,6 0)))'),
 *         ('PolyhedralSurface', '(((0 0,4 0,0 4,0 0)))', '(((0 0,4 0,4 4,0 4,0 0)),((4 0,8 0,8 4,4 4,4 0)))'),
 *         ('TIN', '(((0 0,4 0,0 4,0 0)))', '(((0 0,4 0,0 4,0 0)),((4 0,4 4,0 4,4 0)))'),
 *         ('Triangle', '((0 0,4 0,0 4,0 0))', '((-3.125 1.5,4.25 -2.5,1.75 5.125,-3.125 1.5))')
 * ), geometries_xy AS (
 *     SELECT type_geometrique,
 *            (type_geometrique || ' EMPTY')::geometry AS vide,
 *            (type_geometrique || simple_xy)::geometry AS simple,
 *            (type_geometrique || complexe_xy)::geometry AS complexe
 *     FROM exemples
 * )
 * SELECT ST_AsText(v.geom, 17) AS wkt,
 *        encode(ST_AsBinary(v.geom, 'NDR'), 'hex') AS ndr,
 *        encode(ST_AsBinary(v.geom, 'XDR'), 'hex') AS xdr
 * FROM geometries_xy AS g
 * CROSS JOIN LATERAL (
 *     VALUES
 *         (1, g.vide),
 *         (2, g.simple),
 *         (3, g.complexe),
 *         (4, ST_Force3DZ(g.simple, 12.5)),
 *         (5, ST_Force3DM(g.simple, -7.25)),
 *         (6, ST_Force4D(g.simple, 12.5, -7.25)),
 *         (7, ST_Force4D(g.complexe, -2.5, 37.125)),
 *         (8, ST_Force4D(g.vide))
 * ) AS v(numero, geom)
 * ORDER BY g.type_geometrique, v.numero
 *
 * Each WKT is also converted again with the following query, binding :ordre
 * to NDR and then XDR, and compared with the corresponding corpus value:
 *
 * SELECT encode(ST_AsBinary(ST_GeomFromText(:wkt), :ordre), 'hex')
 */
final class PostgisTest extends TestCase
{
    /**
     * Provide reference geometries keyed by their PostGIS WKT.
     *
     * Each dataset contains, in order:
     * Key. The PostGIS WKT.
     * 0.   The explicitly constructed expected geometry.
     * 1.   The hexadecimal WKB in NDR (little-endian) byte order provided by PostGIS.
     * 2.   The hexadecimal WKB in XDR (big-endian) byte order provided by PostGIS.
     *
     * @return iterable<string, array{0: SpatialInterface, 1: string, 2: string}>
