    /**
     * Both byte orders must produce the explicitly constructed object graph.
     *
     * @param SpatialInterface $expected explicit geometry
     * @param string           $ndr      little-endian WKB
     * @param string           $xdr      big-endian WKB
     */
    #[DataProvider('geometries')]
    public function testDecode(SpatialInterface $expected, string $ndr, string $xdr): void
    {
        foreach (['NDR' => $ndr, 'XDR' => $xdr] as $order => $hex) {
            $actual = new WkbDecoderStrategy()->decode(pack('H*', $hex));
            self::assertEquals($expected, $actual, $order);
            self::assertSame($expected->toArray(), $actual->toArray(), $order);
        }
    }

    /**
     * These PostGIS representations exceed the current domain/decoder support.
     *
     * @param string $hex unsupported WKB
     */
    #[DataProvider('unsupportedGeometries')]
    public function testUnsupportedGeometry(string $hex): void
    {
        $this->expectException(InvalidArgumentException::class);
        new WkbDecoderStrategy()->decode(pack('H*', $hex));
    }
}
